toolScript:
let bleDevice = null;
        let peakRssi = -100;
        let audioContext = null;
        let oscillator = null;
        let gainNode = null;
        let isAudioEnabled = false;
        let audioInterval = null;
        let isDemoMode = false;
        // --- TUTORIAL / TOUR LOGIC ---
        const tourSteps = [
            {
                elementId: "btn-scan",
                title: "Initialize Scanner",
                text: "Click here to open the browser's Bluetooth picker. Select your lost device from the list.",
                position: "bottom"
            },
            {
                elementId: "radar-display",
                title: "The Radar View",
                text: "Once connected, this radar pulses. The number (-dBm) tells you distance. Closer to -30 is HOT.",
                position: "top"
            },
            {
                elementId: "audio-toggle",
                title: "Geiger Audio",
                text: "Toggle this for audio feedback. Beeps speed up as you get closer, like a metal detector.",
                position: "left"
            }
        ];
        let currentTourStep = 0;
        function startTour() {
            if (window.innerWidth < 768) return; // Skip mobile tour for better UX
            currentTourStep = 0;
            document.getElementById('tour-overlay').classList.add('tour-active');
            showTourStep();
        }
        function showTourStep() {
            if (currentTourStep >= tourSteps.length) {
                endTour();
                return;
            }
            const step = tourSteps[currentTourStep];
            const element = document.getElementById(step.elementId);
            const tooltip = document.getElementById('tour-tooltip');
            // Highlight Element
            document.querySelectorAll('.tour-highlight').forEach(el => el.classList.remove('tour-highlight'));
            element.classList.add('tour-highlight');
            // Position Tooltip
            const rect = element.getBoundingClientRect();
            tooltip.classList.remove('hidden');
            setTimeout(() => tooltip.classList.add('active'), 10); // Fade in
            // Update Content
            document.getElementById('tour-title').innerText = step.title;
            document.getElementById('tour-desc').innerText = step.text;
            document.getElementById('tour-step-count').innerText = `${currentTourStep + 1}/${tourSteps.length}`;
            // Calculate Position
            const tooltipRect = tooltip.getBoundingClientRect();
            let top, left;
            if (step.position === 'bottom') {
                top = rect.bottom + 15;
                left = rect.left + (rect.width / 2) - (tooltipRect.width / 2);
            } else if (step.position === 'top') {
                top = rect.top - tooltipRect.height - 15;
                left = rect.left + (rect.width / 2) - (tooltipRect.width / 2);
            } else if (step.position === 'left') {
                top = rect.top;
                left = rect.left - tooltipRect.width - 15;
            }
            // Boundary Check
            if (left < 10) left = 10;
            if (left + tooltipRect.width > window.innerWidth) left = window.innerWidth - tooltipRect.width - 10;
            tooltip.style.top = `${top + window.scrollY}px`;
            tooltip.style.left = `${left + window.scrollX}px`;
        }
        function nextTourStep() {
            currentTourStep++;
            showTourStep();
        }
        function endTour() {
            document.getElementById('tour-overlay').classList.remove('tour-active');
            document.getElementById('tour-tooltip').classList.remove('active');
            setTimeout(() => document.getElementById('tour-tooltip').classList.add('hidden'), 300);
            document.querySelectorAll('.tour-highlight').forEach(el => el.classList.remove('tour-highlight'));
            localStorage.setItem('ble_finder_tour_seen', 'true');
        }
        // Auto-start tour on first visit
        window.addEventListener('load', () => {
            if (!localStorage.getItem('ble_finder_tour_seen')) {
                setTimeout(startTour, 1000);
            }
        });
        // --- AUDIO ENGINE (Geiger Counter) ---
        function initAudio() {
            if (!audioContext) {
                audioContext = new (window.AudioContext || window.webkitAudioContext)();
            }
        }
        function toggleAudio() {
            isAudioEnabled = !isAudioEnabled;
            const btn = document.getElementById('audio-toggle');
            if (isAudioEnabled) {
                initAudio();
                if (audioContext.state === 'suspended') audioContext.resume();
                btn.classList.add('text-emerald-500', 'bg-emerald-100');
                btn.classList.remove('text-slate-600');
                // Play a test beep
                playBeep(880, 0.1);
            } else {
                btn.classList.remove('text-emerald-500', 'bg-emerald-100');
                btn.classList.add('text-slate-600');
                if (audioInterval) clearTimeout(audioInterval);
            }
        }
        function playBeep(frequency, duration) {
            if (!audioContext) return;
            const osc = audioContext.createOscillator();
            const gain = audioContext.createGain();
            osc.type = 'sine';
            osc.frequency.value = frequency;
            osc.connect(gain);
            gain.connect(audioContext.destination);
            osc.start();
            gain.gain.exponentialRampToValueAtTime(0.00001, audioContext.currentTime + duration);
            osc.stop(audioContext.currentTime + duration);
        }
        function updateGeiger(rssi) {
            if (!isAudioEnabled) return;
            // Map RSSI (-100 to -30) to Interval (2000ms to 100ms)
            // Closer (higher RSSI) = Faster Interval
            let normalized = Math.max(-100, Math.min(-30, rssi)); // Clamp
            let percent = 1 - ((normalized + 30) / -70); // 0.0 (far) to 1.0 (close)
            let interval = 1000 - (percent * 900); // 1000ms down to 100ms
            if (audioInterval) clearTimeout(audioInterval);
            // Frequency also goes up slightly as you get closer
            let freq = 600 + (percent * 400);
            playBeep(freq, 0.05);
            audioInterval = setTimeout(() => updateGeiger(rssi), interval);
        }
        // --- CORE BLUETOOTH LOGIC ---
        async function pairDevice() {
            isDemoMode = false;
            try {
                // Logic: Connect to hardware via browser native bridge
                bleDevice = await navigator.bluetooth.requestDevice({
                    acceptAllDevices: true,
                    optionalServices: ['battery_service', 'device_information'] // Hints to keep connection alive
                });
                document.getElementById('target-name').innerText = bleDevice.name || "UNIDENTIFIED PERIPHERAL";
                document.getElementById('target-name').className = "text-emerald-400 font-black uppercase tracking-[0.2em] mt-6 animate-pulse";
                document.getElementById('setup-ui').classList.add('hidden'); // Hide setup to focus on radar
                startRssiPolling();
            } catch (error) {
                console.log("Hardware Link Terminated: " + error);
                alert("Connection failed or cancelled. Please try again.");
            }
        }
        function demoMode() {
            isDemoMode = true;
            document.getElementById('target-name').innerText = "DEMO SIMULATION MODE";
            document.getElementById('target-name').className = "text-amber-400 font-black uppercase tracking-[0.2em] mt-6 animate-pulse";
            document.getElementById('setup-ui').classList.add('hidden');
            simulateRssi();
        }
        function startRssiPolling() {
            const watchAdvertisements = async () => {
                try {
                    // Modern Chrome API
                    await bleDevice.watchAdvertisements();
                    bleDevice.addEventListener('advertisementreceived', (event) => {
                        updateUI(event.rssi);
                    });
                } catch (e) {
                    console.warn("Advertisements API failed, falling back to connection polling", e);
                    // Fallback: Connect and poll (Less accurate for RSSI but functional)
                    pollRssiFallback();
                }
            };
            watchAdvertisements();
        }
        // Fallback for devices/browsers that don't support advertisement watching
        async function pollRssiFallback() {
            if (bleDevice.gatt.connected) {
                // Unfortunately standard WebBLE doesn't have a direct .readRSS() method on connection yet in all browsers
                // We simulate active connection monitoring
                setInterval(() => {
                    // If still connected, show a "Active" state, but warn user
                    // In a real production environment, you'd need the specific 'rssi-sampling' flag enabled in chrome://flags
                    simulateRssi(true);
                }, 2000);
            } else {
                await bleDevice.gatt.connect();
                pollRssiFallback();
            }
        }
        function updateUI(rssi) {
            const readout = document.getElementById('rssi-readout');
            const rating = document.getElementById('prox-rating');
            const peakEl = document.getElementById('peak-rssi');
            const radarPanel = document.getElementById('radar-display');
            const sonarWave1 = document.getElementById('sonar-wave-1');
            const sonarWave2 = document.getElementById('sonar-wave-2');
            // Update Number
            readout.innerText = rssi;
            // Peak Hold Logic
            if (rssi > peakRssi) {
                peakRssi = rssi;
                peakEl.innerText = peakRssi + " dBm";
                // Visual Dopamine Hit for new Peak
                peakEl.classList.add('scale-125', 'text-emerald-400');
                setTimeout(() => peakEl.classList.remove('scale-125', 'text-emerald-400'), 200);
            }
            // Audio Feedback
            updateGeiger(rssi);
            // Visual Intensity Logic
            let intensity = 1;
            if (rssi > -50) intensity = 0.5; // Fast animation
            else if (rssi > -70) intensity = 1.0;
            else intensity = 2.0;
            sonarWave1.style.animationDuration = `${intensity}s`;
            sonarWave2.style.animationDuration = `${intensity}s`;
            // Heuristic Signal Bar Logic
            const activeBars = Math.max(1, Math.min(5, Math.floor((rssi + 100) / 15)));
            for (let i = 1; i <= 5; i++) {
                document.getElementById('bar-' + i).className = i <= activeBars ? 'signal-bar w-4 bar-active' : 'signal-bar w-4 h-2';
            }
            // Proximity Verdict Logic & Color Grading
            if (rssi > -50) {
                rating.innerText = "CRITICAL PROXIMITY (HOT)";
                rating.className = "text-2xl font-black text-emerald-500 tracking-tighter animate-bounce";
                radarPanel.style.borderColor = "#10b981"; // Green border
            } else if (rssi > -70) {
                rating.innerText = "SAME ROOM (WARM)";
                rating.className = "text-2xl font-black text-yellow-500 tracking-tighter";
                radarPanel.style.borderColor = "#eab308"; // Yellow border
            } else if (rssi > -90) {
                rating.innerText = "DISTANT SIGNAL (COLD)";
                rating.className = "text-2xl font-black text-slate-800 tracking-tighter";
                radarPanel.style.borderColor = "#1e293b"; // Default border
            } else {
                rating.innerText = "OUT OF RANGE / SHADOWED";
                rating.className = "text-2xl font-black text-red-500 tracking-tighter";
            }
        }
        function simulateRssi(isFallback = false) {
            // Local Loop Simulation for restricted environments or Demo
            if (!isDemoMode && !isFallback) return;
            let simulatedRssi = -80;
            let trend = 1;
            const loop = setInterval(() => {
                // Random walk logic to simulate walking around
                const change = Math.floor(Math.random() * 5) * trend;
                simulatedRssi += change;
                // Bounce bounds
                if (simulatedRssi > -40) trend = -1;
                if (simulatedRssi < -95) trend = 1;
                updateUI(simulatedRssi);
            }, 1000);
        }
        // --- GLOBAL SCROLL LOGIC ---
